    if(v&&typeof verbTail==="function"){let ws=v.split(/\s+/); while(ws.length>1&&verbTail(ws[ws.length-1]))ws.pop(); v=ws.join(" ");}
    if(!v||v.length<2||NER_DROP.has(v)||NER_DROP.has(norm(v)))continue;
