    // "נ ג ד" מכותרת התיק חזר מהמודל כשם אדם
    {const vw=norm(v).split(/\s+/); if(vw.length>1&&vw.every(x=>x.replace(/['"׳״]/g,"").length<=1))continue;}
    let kind=NER_KIND[e.type];
    // "שחר - שירותי חברה רווחה משפחה" סומן כאדם. שם עם מקף מפריד או
